# value -> dataset (view.custom.sourceData.schedule)

def getv(r, k, default=None):
	try:
		return r[k]
	except Exception:
		try:
			return r.getValue(k)
		except Exception:
			try:
				return r.get(k, default)
			except Exception:
				return default

def to_int(x, d=None):
	try:
		return int(x)
	except:
		return d

def clamp(v, lo, hi):
	try:
		return max(lo, min(hi, v))
	except:
		return v

def valid_due(dt):
	try:
		return (dt is not None) and (system.date.getYear(dt) >= 2000)
	except:
		return False

def shade(hex_color, pct):
	# pct in [-1, +1] : - darken, + lighten
	try:
		h = hex_color.lstrip('#')
		r = int(h[0:2], 16)
		g = int(h[2:4], 16)
		b = int(h[4:6], 16)
		r = int(clamp(r + pct*255, 0, 255))
		g = int(clamp(g + pct*255, 0, 255))
		b = int(clamp(b + pct*255, 0, 255))
		return '#%02x%02x%02x' % (r, g, b)
	except:
		return hex_color

def wo_compact(wo):
	# '25-8912P-10-1S01' -> '8912-1S01', fallback last 10 chars
	try:
		parts = (wo or '').split('-')
		if len(parts) >= 4:
			middle = parts[1].replace('P','')
			last   = parts[-1]
			return '%s-%s' % (middle, last)
		return (wo or '')[-10:]
	except:
		return (wo or '')[-10:]

# ---------- INDUSTRIAL PALETTE ----------
# Muted, low-saturation “shop floor” colors
BRAND = {
	'plasma':  '#2F6B8A',  # steel blue
	'bend':    '#2F7F7B',  # machine teal
	'seam':    '#3E6C4A',  # tooling green
	'default': '#5B6773'   # slate
}

def op_color(op):
	k = (op or '').lower()
	if   k.startswith('pla'): return BRAND['plasma']
	elif k.startswith('ben'): return BRAND['bend']
	elif k.startswith('sea'): return BRAND['seam']
	return BRAND['default']

# compact labels by visible window
try:
	start = self.view.custom.viewData.startTime
	end   = self.view.custom.viewData.endTime
	visible_hours = abs(system.date.hoursBetween(start, end))
except:
	visible_hours = 48
compact_mode = (visible_hours <= 48)

# running schedule IDs -> progress bump
running = set()
try:
	rds = self.view.custom.sourceData.runningIds
	for r in system.dataset.toPyDataSet(rds):
		sid = to_int(getv(r, 'ScheduleID'))
		if sid is not None:
			running.add(sid)
except:
	pass

now = system.date.now()
events = []

try:
	ds = system.dataset.toPyDataSet(value) if value is not None else None
except:
	ds = None

if ds:
	for row in ds:
		try:
			schedId = to_int(getv(row, 'ID'))
			lineId  = to_int(getv(row, 'LineID'))
			if schedId is None or lineId is None:
				continue

			wo   = getv(row, 'WorkOrder') or ''
			op   = (getv(row, 'ProductionVersion') or 'Op').strip()
			pc   = getv(row, 'ProductCode') or ''
			qty  = to_int(getv(row, 'Quantity'), 1)
			due  = getv(row, 'RequiredEndDate')

			startDate = getv(row, 'ScheduleStartDateTime')
			endDate   = getv(row, 'ScheduleEndDateTime')

			# time-based progress (fallback if running)
			percent = 0
			try:
				if startDate and endDate and system.date.after(now, startDate):
					total_ms   = float(system.date.millisBetween(startDate, endDate))
					elapsed_ms = float(system.date.millisBetween(startDate, now))
					if total_ms > 0:
						percent = clamp(int(100.0 * elapsed_ms / total_ms), 0, 100)
			except:
				pass
			if schedId in running:
				percent = max(10, percent)

			# due cues -> border color
			borderClr = 'rgba(0,0,0,0.10)'
			if valid_due(due):
				try:
					if endDate and system.date.after(endDate, due):
						borderClr = '#C84B31'   # muted red for overdue
					else:
						hrs = abs(system.date.hoursBetween(endDate, due))
						if hrs <= 24:
							borderClr = '#B8872E' # muted amber for due soon
				except:
					pass

			# colors (very subtle gradient)
			bg_base = op_color(op)
			bg_top  = shade(bg_base,  0.03)
			bg_bot  = shade(bg_base, -0.04)

			# labels (ASCII only)
			if compact_mode:
				op_letter = (op[:1] or 'O').upper()
				label = '[%s] %s' % (op_letter, wo_compact(wo))
				font_sz = '11px'
				pad_lr  = 6
			else:
				parts = [wo]
				if pc:  parts += ['• ' + pc]
				if op:  parts += ['• ' + op]
				if qty: parts += ['• Qty %s' % qty]
				label = '  '.join(parts)
				font_sz = '12px'
				pad_lr  = 10

			shadow = '0 1px 2px rgba(0,0,0,0.12)'
			if schedId in running:
				shadow = '0 0 0 2px rgba(255,255,255,0.15), 0 0 10px rgba(0,0,0,0.20)'

			events.append({
				'itemId':      lineId,
				'eventId':     str(schedId),
				'startDate':   startDate,
				'endDate':     endDate,
				'label':       label,
				'percentDone': percent,
				'leadTime':    0,
				'style': {
					'backgroundImage': 'linear-gradient(180deg, %s 0%%, %s 100%%)' % (bg_top, bg_bot),
					'color':           '#F4F5F7',     # off-white for legibility
					'borderRadius':    8,
					'border':          '1px solid %s' % borderClr,
					'boxShadow':       shadow,
					'paddingLeft':     pad_lr,
					'paddingRight':    pad_lr,
					'fontSize':        font_sz,
					'fontWeight':      '600',
					'letterSpacing':   '0.2px'
				}
			})
		except:
			pass

return events
